        </div>
        <div className="text-right">
          <span className={`inline-flex rounded-full px-3 py-1 text-xs font-semibold ${QUOTE_STYLES[quote.status] || QUOTE_STYLES.draft}`}>
            {(quote.status || "draft").replace(/_/g, " ")}
